// Finite Stage PF registry and storage images use only supplied typed APIs.
// BEGIN_MP4_PROFLARE_REGISTRY_SCOPE
// Registry storage belongs to the original ProFlare batch. A held callback may
// change occupancy, never replace storage or introduce an unleased flare. The
// adapter verifies the exact source List/Queue/Dictionary field and method
// layouts; this scope retains every managed reference and restores every slot.
namespace idoly_mp4_proflare_registry {
constexpr size_t max_rows = 256, max_flares = 128, max_roots = 1024;
enum class Result : uint8_t {
  ok,
  unowned,
  unsupported,
  stale,
  failed,
  invalid
};
enum class Operation : uint8_t { enable, disable, start };
enum class DataOperation : uint8_t { update, retire, abandon };
struct Flare {
  void *object = nullptr, *atlas = nullptr;
  uintptr_t native = 0;
  int32_t instance = 0;
  uint64_t initialized = 0;
};
struct List {
  void *object = nullptr, *array = nullptr, *sync = nullptr;
  void **rows = nullptr;
  uint32_t count = 0, version = 0;
  size_t capacity = 0;
};
struct Queue {
  void *object = nullptr, *array = nullptr, *sync = nullptr;
  int32_t *rows = nullptr;
  uint32_t head = 0, tail = 0, count = 0, version = 0;
  size_t capacity = 0;
};
struct Entry {
  int32_t hash = -1, next = -1, key = 0, value = 0;
};
struct Dictionary {
  void *object = nullptr, *buckets = nullptr, *entries = nullptr;
  void *comparer = nullptr, *keys = nullptr, *values = nullptr, *sync = nullptr;
  int32_t *bucket_rows = nullptr;
  Entry *rows = nullptr;
  uint32_t count = 0, version = 0, free_count = 0;
  int32_t free_list = -1;
  size_t bucket_capacity = 0, capacity = 0;
};
struct Image {
  void *batch = nullptr, *atlas = nullptr;
  uintptr_t native = 0;
  List list{}, data{};
  Queue queue{};
  Dictionary dictionary{};
};
struct Api {
  bool (*current)(void *, uint64_t) = nullptr;
  bool (*held)(void *) = nullptr;
  bool (*read)(void *, Image *) = nullptr;
  bool (*flare)(void *, const Flare &) = nullptr;
  int32_t (*instance)(void *, void *) = nullptr;
  uint64_t (*origin)(void *, void *, Operation) = nullptr;
  bool (*write)(void *, const Image &, void *const *, const int32_t *,
                const int32_t *, const Entry *, void *const *) = nullptr;
  uint32_t (*retain)(void *) = nullptr;
  void *(*target)(uint32_t) = nullptr;
  void (*release)(uint32_t) = nullptr;
  uint64_t (*data_origin)(void *, DataOperation, void *, void *) = nullptr;
  bool (*data_complete)(void *, DataOperation, void *, void *,
                        uint64_t) = nullptr;

  bool valid() const {
    return current && held && read && flare && instance && origin && write &&
           retain && target && release;
  }
};
class Scope {
  struct Snapshot {
    Image image{};
    void *list[max_rows]{}, *data[max_rows]{};
    int32_t queue[max_rows]{}, buckets[max_rows]{};
    Entry entries[max_rows]{};
  } saved_{}, live_{};
  struct Root {
    void *object = nullptr;
    uint32_t handle = 0;
  } roots_[max_roots]{};
  Flare flares_[max_flares]{};
  Api api_{};
  void *ctx_ = nullptr;
  uint64_t epoch_ = 0, in_flight_ = 0;
  void *receiver_ = nullptr;
  Operation operation_ = Operation::start;
  size_t count_ = 0, root_count_ = 0;
  bool captured_ = false, failed_ = false;
  struct Born {
    void *data = nullptr, *camera = nullptr;
    uint64_t receipt = 0;
    bool live = false;
  } born_[32]{};
  size_t born_count_ = 0;
  bool data_in_flight_ = false;
  DataOperation data_operation_ = DataOperation::update;
  void *data_camera_ = nullptr, *data_receiver_ = nullptr;

  const char *error_ = "none";
  Result fail(Result r, const char *s) {
    error_ = s;
    return r;
  }
  bool keep(void *o) {
    if (!o)
      return true;
    for (size_t i = 0; i < root_count_; ++i)
      if (roots_[i].object == o)
        return api_.target(roots_[i].handle) == o;
    if (root_count_ == max_roots)
      return false;
    auto h = api_.retain(o);
    if (!h || api_.target(h) != o) {
      if (h)
        api_.release(h);
      return false;
    }
    roots_[root_count_++] = {o, h};
    return true;
  }
  static bool same_list(const List &a, const List &b) {
    return a.object == b.object && a.array == b.array && a.sync == b.sync &&
           a.rows == b.rows && a.capacity == b.capacity;
  }
  static bool same_structure(const Image &a, const Image &b, bool data = true) {
    const auto &x = a.queue;
    const auto &y = b.queue;
    const auto &d = a.dictionary;
    const auto &e = b.dictionary;
    return a.batch == b.batch && a.native == b.native &&
           same_list(a.list, b.list) && (!data || same_list(a.data, b.data)) &&
           x.object == y.object && x.array == y.array && x.sync == y.sync &&
           x.rows == y.rows && x.capacity == y.capacity &&
           d.object == e.object && d.buckets == e.buckets &&
           d.entries == e.entries && d.comparer == e.comparer &&
           d.keys == e.keys && d.values == e.values && d.sync == e.sync &&
           d.bucket_rows == e.bucket_rows && d.rows == e.rows &&
           d.bucket_capacity == e.bucket_capacity && d.capacity == e.capacity;
  }
  static bool bounded(const Image &s) {
    const auto &l = s.list;
    const auto &d = s.dictionary;
    const auto &q = s.queue;
    return s.batch && s.native && l.object && l.array && l.rows &&
           l.count <= l.capacity && l.capacity <= max_rows && s.data.object &&
           s.data.array && s.data.rows && s.data.count <= s.data.capacity &&
           s.data.capacity <= max_rows && q.object && q.array && q.rows &&
           q.capacity >= l.count && q.capacity <= max_rows &&
           q.count <= q.capacity && q.head < q.capacity &&
           q.tail < q.capacity && d.object && d.buckets && d.entries &&
           d.bucket_rows && d.rows && d.bucket_capacity > 0 &&
           d.bucket_capacity <= max_rows && d.capacity >= l.count &&
           d.capacity <= max_rows && d.count <= d.capacity &&
           d.free_count <= d.count && d.free_list >= -1 &&
           (d.free_list < 0 || static_cast<uint32_t>(d.free_list) < d.count);
  }
  bool logical(const Image &s) {
    if (!bounded(s))
      return false;
    bool free_slots[max_rows]{}, used_entries[max_rows]{},
        free_entries[max_rows]{};
    const auto &q = s.queue;
    const auto &d = s.dictionary;
    const auto &l = s.list;
    if (q.tail != (q.head + q.count) % q.capacity)
      return false;
    for (size_t i = 0; i < q.count; ++i) {
      int32_t slot = q.rows[(q.head + i) % q.capacity];
      if (slot < 0 || static_cast<uint32_t>(slot) >= l.count || l.rows[slot] ||
          free_slots[slot])
        return false;
      free_slots[slot] = true;
    }
    size_t linked = 0;
    for (size_t b = 0; b < d.bucket_capacity; ++b) {
      int32_t at = d.bucket_rows[b] - 1;
      size_t steps = 0;
      while (at != -1) {
        if (at < 0 || static_cast<uint32_t>(at) >= d.count ||
            used_entries[at] || ++steps > d.count)
          return false;
        const auto &e = d.rows[at];
        if (e.hash < 0 ||
            static_cast<size_t>(e.hash) % d.bucket_capacity != b ||
            e.hash != (e.key & 0x7fffffff) || e.value < 0 ||
            static_cast<uint32_t>(e.value) >= l.count || !l.rows[e.value] ||
            api_.instance(ctx_, l.rows[e.value]) != e.key)
          return false;
        used_entries[at] = true;
        ++linked;
        at = e.next;
      }
    }
    int32_t at = d.free_list;
    size_t freed = 0;
    while (at != -1) {
      if (at < 0 || static_cast<uint32_t>(at) >= d.count || free_entries[at] ||
          used_entries[at] || ++freed > d.count)
        return false;
      if (d.rows[at].hash != -1)
        return false;
      free_entries[at] = true;
      at = d.rows[at].next;
    }
    if (freed != d.free_count || linked != d.count - d.free_count)
      return false;
    for (size_t i = 0; i < d.count; ++i)
      if (!used_entries[i] && !free_entries[i])
        return false;
    size_t occupied = 0;
    for (size_t i = 0; i < l.count; ++i) {
      if (!l.rows[i]) {
        if (!free_slots[i])
          return false;
        continue;
      }
      if (free_slots[i])
        return false;
      ++occupied;
      size_t hits = 0;
      for (size_t j = 0; j < d.count; ++j)
        if (used_entries[j] && d.rows[j].value == static_cast<int32_t>(i))
          ++hits;
      if (hits != 1)
        return false;
      for (size_t j = 0; j < i; ++j)
        if (l.rows[j] == l.rows[i])
          return false;
    }
    return occupied == linked && occupied + q.count == l.count;
  }
  static bool same_entry(const Entry &a, const Entry &b) {
    return a.hash == b.hash && a.next == b.next && a.key == b.key &&
           a.value == b.value;
  }
  static void copy(Snapshot &out, const Image &im) {
    out.image = im;
    for (size_t i = 0; i < im.list.capacity; ++i)
      out.list[i] = im.list.rows[i];
    for (size_t i = 0; i < im.data.capacity; ++i)
      out.data[i] = im.data.rows[i];
    for (size_t i = 0; i < im.queue.capacity; ++i)
      out.queue[i] = im.queue.rows[i];
    for (size_t i = 0; i < im.dictionary.bucket_capacity; ++i)
      out.buckets[i] = im.dictionary.bucket_rows[i];
    for (size_t i = 0; i < im.dictionary.capacity; ++i)
      out.entries[i] = im.dictionary.rows[i];
  }
  bool exact(const Snapshot &s, const Image &n, bool data = true) {
    const auto &a = s.image;
    const auto &d = a.dictionary;
    const auto &e = n.dictionary;
    if (!same_structure(a, n, data) || a.atlas != n.atlas ||
        a.list.count != n.list.count || a.list.version != n.list.version ||
        (data &&
         (a.data.count != n.data.count || a.data.version != n.data.version)) ||
        a.queue.head != n.queue.head || a.queue.tail != n.queue.tail ||
        a.queue.count != n.queue.count || a.queue.version != n.queue.version ||
        d.count != e.count || d.version != e.version ||
        d.free_count != e.free_count || d.free_list != e.free_list)
      return false;
    for (size_t i = 0; i < a.list.capacity; ++i)
      if (s.list[i] != n.list.rows[i])
        return false;
    for (size_t i = 0; data && i < a.data.capacity; ++i)
      if (s.data[i] != n.data.rows[i])
        return false;
    for (size_t i = 0; i < a.queue.capacity; ++i)
      if (s.queue[i] != n.queue.rows[i])
        return false;
    for (size_t i = 0; i < d.bucket_capacity; ++i)
      if (s.buckets[i] != e.bucket_rows[i])
        return false;
    for (size_t i = 0; i < d.capacity; ++i)
      if (!same_entry(s.entries[i], e.rows[i]))
        return false;
    return true;
  }
  bool identity() {
    if (!captured_ || !api_.current(ctx_, epoch_))
      return false;
    for (size_t i = 0; i < root_count_; ++i)
      if (api_.target(roots_[i].handle) != roots_[i].object)
        return false;
    for (size_t i = 0; i < count_; ++i)
      if (!api_.flare(ctx_, flares_[i]))
        return false;
    return true;
  }
  bool read_current(Image &im) {
    return identity() && api_.read(ctx_, &im) && logical(im) &&
           exact(live_, im);
  }
  bool selected(void *o) const {
    for (size_t i = 0; i < count_; ++i)
      if (flares_[i].object == o)
        return true;
    return false;
  }

public:
  const char *error() const { return error_; }
  bool active() const { return captured_; }
  bool owns(void *object) const { return captured_ && selected(object); }
  bool current() {
    Image im{};
    return !in_flight_ && !failed_ && read_current(im);
  }
  Result capture(Api api, void *ctx, uint64_t epoch, const Flare *flares,
                 size_t count) {
    if (epoch_ || !api.valid() || !ctx || !epoch || !flares || !count ||
        count > max_flares)
      return fail(Result::invalid, "proflare_registry_bad_capture");
    api_ = api;
    ctx_ = ctx;
    epoch_ = epoch;
    Image im{};
    if (!api_.current(ctx_, epoch_) || !api_.held(ctx_) ||
        !api_.read(ctx_, &im) || !logical(im))
      return fail(Result::unsupported, "proflare_registry_source_unclosed");
    for (size_t i = 0; i < count; ++i) {
      const auto &f = flares[i];
      if (!f.object || !f.native || !f.atlas || !f.initialized ||
          !api_.flare(ctx_, f) || api_.instance(ctx_, f.object) != f.instance)
        return fail(Result::unsupported, "proflare_start_birth_unclosed");
      for (size_t j = 0; j < i; ++j)
        if (flares[j].object == f.object || flares[j].instance == f.instance)
          return fail(Result::unsupported, "proflare_registry_duplicate_flare");
      if ((i && flares[0].atlas != f.atlas) ||
          (im.atlas && im.atlas != f.atlas))
        return fail(Result::unsupported,
                    "proflare_registry_atlas_cohort_changed");
      flares_[count_++] = f;
      if (!keep(f.object) || !keep(f.atlas))
        return fail(Result::failed, "proflare_registry_retain_failed");
    }
    size_t missing = 0;
    for (size_t i = 0; i < count_; ++i) {
      size_t hits = 0;
      for (size_t j = 0; j < im.list.count; ++j)
        hits += im.list.rows[j] == flares_[i].object;
      if (!hits)
        ++missing;
    }
    if (missing + im.list.count - im.queue.count > im.list.capacity ||
        missing + im.list.count - im.queue.count > im.queue.capacity ||
        missing + im.list.count - im.queue.count > im.dictionary.capacity)
      return fail(Result::unsupported, "proflare_registry_capacity_unclosed");
    const auto &d = im.dictionary;
    void *objects[] = {im.batch,       im.atlas,      im.list.object,
                       im.list.array,  im.list.sync,  im.queue.object,
                       im.queue.array, im.queue.sync, d.object,
                       d.buckets,      d.entries,     d.comparer,
                       d.keys,         d.values,      d.sync,
                       im.data.object, im.data.array, im.data.sync};
    for (auto *o : objects)
      if (!keep(o))
        return fail(Result::failed, "proflare_registry_retain_failed");
    for (size_t i = 0; i < im.list.capacity; ++i)
      if (!keep(im.list.rows[i]))
        return fail(Result::failed, "proflare_registry_retain_failed");
    for (size_t i = 0; i < im.data.capacity; ++i)
      if (!keep(im.data.rows[i]))
        return fail(Result::failed, "proflare_registry_retain_failed");
    copy(saved_, im);
    copy(live_, im);
    captured_ = true;
    return current() ? Result::ok
                     : fail(Result::stale, "proflare_registry_capture_changed");
  }
  Result begin(void *flare, Operation op, uint64_t *receipt) {
    if (!captured_ || !selected(flare))
      return Result::unowned;
    if (!receipt || in_flight_ || failed_ || !api_.held(ctx_) || !current())
      return fail(Result::stale, "proflare_registry_callback_changed");
    auto token = api_.origin(ctx_, flare, op);
    if (!token)
      return fail(Result::unsupported, "proflare_registry_origin_missing");
    in_flight_ = token;
    receiver_ = flare;
    operation_ = op;
    *receipt = token;
    return Result::ok;
  }
  Result end(uint64_t token, bool completed) {
    if (!in_flight_ || data_in_flight_ || token != in_flight_)
      return fail(Result::invalid, "proflare_registry_callback_order");
    bool origin = api_.origin(ctx_, receiver_, operation_) == token;
    void *receiver = receiver_;
    in_flight_ = 0;
    receiver_ = nullptr;
    Image im{};
    if (!completed || !origin || !identity() || !api_.held(ctx_) ||
        !api_.read(ctx_, &im) || !logical(im) ||
        !same_structure(live_.image, im)) {
      failed_ = true;
      return fail(Result::failed, "proflare_registry_original_changed_storage");
    }
    const auto &old = live_.image;
    if (im.list.count < old.list.count || im.list.count > old.list.count + 1 ||
        (im.list.count != old.list.count &&
         (operation_ == Operation::disable || old.queue.count != 0)) ||
        im.data.count != old.data.count ||
        im.data.version != old.data.version) {
      failed_ = true;
      return fail(Result::failed, "proflare_registry_original_changed_count");
    }
    for (size_t i = 0; i < im.data.capacity; ++i)
      if (im.data.rows[i] != live_.data[i]) {
        failed_ = true;
        return fail(Result::failed, "proflare_registry_data_birth_unleased");
      }
    size_t before = 0, after = 0;
    for (size_t i = 0; i < im.list.capacity; ++i) {
      void *a = live_.list[i], *b = im.list.rows[i];
      before += a == receiver;
      after += b == receiver;
      if (a != b && !((a == receiver && !b) || (!a && b == receiver))) {
        failed_ = true;
        return fail(Result::failed, "proflare_registry_unrelated_slot_changed");
      }
    }
    if ((operation_ == Operation::disable && after) ||
        (operation_ != Operation::disable && after != 1) || before > 1) {
      failed_ = true;
      return fail(Result::failed, "proflare_registry_wrong_occupancy");
    }
    void *atlas = nullptr;
    for (size_t i = 0; i < count_; ++i)
      if (flares_[i].object == receiver)
        atlas = flares_[i].atlas;
    if (im.atlas && im.atlas != atlas && im.atlas != old.atlas) {
      failed_ = true;
      return fail(Result::failed, "proflare_registry_atlas_changed");
    }
    copy(live_, im);
    return current()
               ? Result::ok
               : fail(Result::stale, "proflare_registry_completion_changed");
  }

  bool data_birth(void *data, void *camera, uint64_t *receipt) {
    if (receipt)
      *receipt = 0;
    if (!receipt || !current())
      return false;
    for (size_t i = 0; i < born_count_; ++i)
      if (born_[i].live && born_[i].data == data && born_[i].camera == camera) {
        *receipt = born_[i].receipt;
        return *receipt != 0;
      }
    return false;
  }
  Result begin_data(DataOperation op, void *camera, void *data,
                    uint64_t *receipt) {
    if (receipt)
      *receipt = 0;
    if ((op!=DataOperation::update&&op!=DataOperation::retire)||
        !receipt || !camera || !api_.data_origin || !api_.data_complete ||
        in_flight_ || data_in_flight_ || !current() || !api_.held(ctx_))
      return fail(Result::unsupported, "proflare_data_operation_unclosed");
    if (op == DataOperation::retire) {
      bool found = false;
      for (size_t i = 0; i < born_count_; ++i)
        found |=
            born_[i].live && born_[i].data == data && born_[i].camera == camera;
      if (!data || !found)
        return fail(Result::unsupported, "proflare_data_retire_unowned");
    }
    auto token = api_.data_origin(ctx_, op, camera, data);
    if (!token)
      return fail(Result::unsupported, "proflare_data_origin_missing");
    in_flight_ = token;
    data_in_flight_ = true;
    data_operation_ = op;
    data_camera_ = camera;
    data_receiver_ = data;
    *receipt = token;
    return Result::ok;
  }
  Result end_data(uint64_t token, void *data, bool completed) {
    if (!in_flight_ || !data_in_flight_ || token != in_flight_)
      return fail(Result::invalid, "proflare_data_operation_order");
    const auto op = data_operation_;
    void *camera = data_camera_;
    void *expected = data_receiver_;
    in_flight_ = 0;
    data_in_flight_ = false;
    data_camera_ = data_receiver_ = nullptr;
    Image im{};
    if (!completed || !api_.data_complete(ctx_, op, camera, data, token) ||
        !identity() || !api_.held(ctx_) || !api_.read(ctx_, &im) ||
        !logical(im) || !exact(live_, im, false)) {
      failed_ = true;
      return fail(Result::failed, "proflare_data_original_unverified");
    }
    const auto &before = live_.image.data;
    const auto &after = im.data;
    if (after.object != before.object || after.sync != before.sync ||
        after.capacity < before.capacity || after.capacity > max_rows) {
      failed_ = true;
      return fail(Result::failed, "proflare_data_storage_changed");
    }
    if (op == DataOperation::update) {
      size_t existing = 0;
      for (size_t i = 0; i < before.count; ++i)
        existing += live_.data[i] == data;
      if (after.count == before.count) {
        if (!same_list(before, after) || after.version != before.version) {
          failed_ = true;
          return fail(Result::failed, "proflare_data_existing_list_changed");
        }
        for (size_t i = 0; i < before.capacity; ++i)
          if (after.rows[i] != live_.data[i]) {
            failed_ = true;
            return fail(Result::failed, "proflare_data_existing_row_changed");
          }
        if ((expected && expected != data) || (data && existing != 1)) {
          failed_ = true;
          return fail(Result::failed, "proflare_data_result_unmapped");
        }
      } else {
        if (!data || existing || (expected && expected != data) ||
            after.count != before.count + 1 ||
            after.version != uint32_t(before.version + 1) ||
            (before.count < before.capacity && !same_list(before, after)) ||
            after.rows[before.count] != data || born_count_ == 32) {
          failed_ = true;
          return fail(Result::failed, "proflare_data_birth_shape_unverified");
        }
        for (size_t i = 0; i < before.count; ++i)
          if (after.rows[i] != live_.data[i]) {
            failed_ = true;
            return fail(Result::failed, "proflare_data_birth_prefix_changed");
          }
        for (size_t i = after.count; i < after.capacity; ++i)
          if (after.rows[i]) {
            failed_ = true;
            return fail(Result::failed, "proflare_data_birth_tail_changed");
          }
        if (!keep(data) || !keep(after.array) || !keep(after.sync)) {
          failed_ = true;
          return fail(Result::failed, "proflare_data_birth_retain_failed");
        }
        born_[born_count_++] = {data, camera, token, true};
        // Keep only grown managed storage as source promotion. Original logical
        // Data-list rows/count/version remain the saved source image.
        saved_.image.data.array = after.array;
        saved_.image.data.rows = after.rows;
        saved_.image.data.capacity = after.capacity;
        for (size_t i = saved_.image.data.count; i < after.capacity; ++i)
          saved_.data[i] = nullptr;
      }
    } else {
      size_t index = before.count, born = born_count_;
      for (size_t i = 0; i < before.count; ++i)
        if (live_.data[i] == expected) {
          if (index != before.count) {
            failed_ = true;
            return fail(Result::failed, "proflare_data_retire_duplicate");
          }
          index = i;
        }
      for (size_t i = 0; i < born_count_; ++i)
        if (born_[i].live && born_[i].data == expected &&
            born_[i].camera == camera)
          born = i;
      if (data != expected || born == born_count_ || index == before.count ||
          after.count + 1 != before.count || !same_list(before, after) ||
          after.version != uint32_t(before.version + 1)) {
        failed_ = true;
        return fail(Result::failed, "proflare_data_retire_shape_changed");
      }
      for (size_t i = 0; i < after.count; ++i)
        if (after.rows[i] != live_.data[i + (i >= index ? 1 : 0)]) {
          failed_ = true;
          return fail(Result::failed, "proflare_data_retire_prefix_changed");
        }
      for (size_t i = after.count; i < after.capacity; ++i)
        if (after.rows[i]) {
          failed_ = true;
          return fail(Result::failed, "proflare_data_retire_tail_changed");
        }
      born_[born].live = false;
    }
    copy(live_, im);
    return current() ? Result::ok
                     : fail(Result::stale, "proflare_data_completion_changed");
  }
  Result abandon_data(uint64_t token, void *data) {
    if (!in_flight_ || !data_in_flight_ ||
        data_operation_ != DataOperation::update || token != in_flight_ ||
        failed_ || !identity() || !api_.held(ctx_))
      return fail(Result::invalid, "proflare_data_abandon_order");
    // The typed outer boundary proves original Try has unwound and its exact
    // partial Data is CPU/GPU-retired. No ordinary callback may grant this.
    if (!api_.data_complete(ctx_, DataOperation::abandon, data_camera_, data,
                            token))
      return fail(Result::unsupported, "proflare_data_abandon_unretired");
    Image im{};
    if (!api_.read(ctx_, &im) || !logical(im) || !exact(live_, im, false))
      return fail(Result::stale, "proflare_data_abandon_registry_changed");
    const auto &before = live_.image.data;
    const auto &after = im.data;
    if (after.object != before.object || after.sync != before.sync ||
        after.capacity < before.capacity || after.count != before.count ||
        (after.version != before.version &&
         after.version != uint32_t(before.version + 2)))
      return fail(Result::stale, "proflare_data_abandon_list_changed");
    for (size_t i = 0; i < before.count; ++i)
      if (after.rows[i] != live_.data[i])
        return fail(Result::stale, "proflare_data_abandon_prefix_changed");
    for (size_t i = after.count; i < after.capacity; ++i)
      if (after.rows[i])
        return fail(Result::stale, "proflare_data_abandon_tail_changed");
    if (!keep(after.array) || !keep(after.sync))
      return fail(Result::failed, "proflare_data_abandon_retain_failed");
    saved_.image.data.array = after.array;
    saved_.image.data.rows = after.rows;
    saved_.image.data.capacity = after.capacity;
    for (size_t i = saved_.image.data.count; i < after.capacity; ++i)
      saved_.data[i] = nullptr;
    copy(live_, im);
    in_flight_ = 0;
    data_in_flight_ = false;
    data_camera_ = data_receiver_ = nullptr;
    return current() ? Result::ok
                     : fail(Result::stale,
                            "proflare_data_abandon_completion_changed");
  }
  Result restore() {
    if (!captured_)
      return Result::ok;
    if (!api_.held(ctx_) || !current())
      return fail(Result::stale, "proflare_registry_restore_changed");
    for (size_t i = 0; i < born_count_; ++i)
      if (born_[i].live)
        return fail(Result::unsupported, "proflare_data_retirement_pending");
    if (!api_.write(ctx_, saved_.image, saved_.list, saved_.queue,
                    saved_.buckets, saved_.entries, saved_.data))
      return fail(Result::failed, "proflare_registry_restore_write_failed");
    copy(live_, saved_.image);
    Image im{};
    if (!api_.read(ctx_, &im) || !exact(saved_, im))
      return fail(Result::failed,
                  "proflare_registry_restore_verification_failed");
    return Result::ok;
  }
  void release() {
    for (size_t i = 0; i < root_count_; ++i)
      if (roots_[i].handle)
        api_.release(roots_[i].handle);
    api_ = {};
    ctx_ = nullptr;
    epoch_ = in_flight_ = 0;
    receiver_ = nullptr;
    count_ = root_count_ = 0;
    captured_ = failed_ = data_in_flight_ = false;
    born_count_ = 0;
    for (auto &b : born_)
      b = {};
    data_camera_ = data_receiver_ = nullptr;
    saved_ = {};
    live_ = {};
    error_ = "none";
  }
};
} // namespace idoly_mp4_proflare_registry
// END_MP4_PROFLARE_REGISTRY_SCOPE

// BEGIN_MP4_PROFLARE_STORAGE_PROMOTION
// Pure logical-image remap after ACTUAL original CPU Start/Init grew managed
// storage. The caller retains the before references and supplies both images
// from exact source adapters under one preparation operation. This does not
// execute callbacks, render, or grant authority to a replacement collection.
namespace idoly_mp4_proflare_registry {
struct PromotedImage {
  Image image{};
  void *list[max_rows]{}, *data[max_rows]{};
  int32_t queue[max_rows]{}, buckets[max_rows]{};
  Entry entries[max_rows]{};
};
class LogicalImage {
  PromotedImage before_{};
  bool captured_ = false;
  static bool arrays(const Image &i) {
    return i.list.count <= i.list.capacity && i.list.capacity <= max_rows &&
           (!i.list.capacity || i.list.rows) &&
           i.data.count <= i.data.capacity && i.data.capacity <= max_rows &&
           (!i.data.capacity || i.data.rows) && i.queue.capacity <= max_rows &&
           i.queue.count <= i.queue.capacity &&
           (!i.queue.capacity || i.queue.rows) &&
           i.dictionary.capacity <= max_rows &&
           i.dictionary.count <= i.dictionary.capacity &&
           i.dictionary.free_count <= i.dictionary.count &&
           i.dictionary.bucket_capacity <= max_rows &&
           (!i.dictionary.capacity || i.dictionary.rows) &&
           (!i.dictionary.bucket_capacity || i.dictionary.bucket_rows) &&
           (!i.queue.count || (i.queue.head < i.queue.capacity &&
                               i.queue.tail < i.queue.capacity));
  }
  static void copy(PromotedImage &o, const Image &i) {
    o.image = i;
    for (size_t j = 0; j < i.list.capacity; ++j)
      o.list[j] = i.list.rows[j];
    for (size_t j = 0; j < i.data.capacity; ++j)
      o.data[j] = i.data.rows[j];
    for (size_t j = 0; j < i.queue.capacity; ++j)
      o.queue[j] = i.queue.rows[j];
    for (size_t j = 0; j < i.dictionary.bucket_capacity; ++j)
      o.buckets[j] = i.dictionary.bucket_rows[j];
    for (size_t j = 0; j < i.dictionary.capacity; ++j)
      o.entries[j] = i.dictionary.rows[j];
  }

public:
  bool capture(const Image &source) {
    if (captured_ || !source.batch || !source.native || !source.list.object ||
        !source.queue.object || !source.dictionary.object ||
        !source.data.object || !arrays(source))
      return false;
    copy(before_, source);
    captured_ = true;
    return true;
  }
  bool restore_image(const Image &storage, PromotedImage *out) const {
    if (!captured_ || !out || !arrays(storage))
      return false;
    const auto &b = before_.image;
    if (storage.batch != b.batch || storage.native != b.native ||
        storage.list.object != b.list.object ||
        storage.list.sync != b.list.sync ||
        storage.queue.object != b.queue.object ||
        storage.queue.sync != b.queue.sync ||
        storage.dictionary.object != b.dictionary.object ||
        storage.dictionary.comparer != b.dictionary.comparer ||
        storage.dictionary.keys != b.dictionary.keys ||
        storage.dictionary.values != b.dictionary.values ||
        storage.dictionary.sync != b.dictionary.sync ||
        storage.list.capacity < b.list.capacity ||
        storage.queue.capacity < b.queue.count ||
        storage.dictionary.capacity < b.dictionary.count ||
        (!storage.dictionary.bucket_capacity && b.dictionary.count))
      return false;
    // CPU Start/Init does not create a per-camera batch-data object. Its source
    // data-list identity and every slot must remain exact; later GPU births
    // have a separate original-render/pass and retirement ledger.
    if (storage.data.object != b.data.object ||
        storage.data.array != b.data.array ||
        storage.data.rows != b.data.rows || storage.data.sync != b.data.sync ||
        storage.data.count != b.data.count ||
        storage.data.version != b.data.version ||
        storage.data.capacity != b.data.capacity)
      return false;
    for (size_t i = 0; i < b.data.capacity; ++i)
      if (storage.data.rows[i] != before_.data[i])
        return false;
    *out = {};
    out->image = storage;
    auto &i = out->image;
    i.atlas = b.atlas;
    i.list.count = b.list.count;
    i.list.version = b.list.version;
    for (size_t j = 0; j < b.list.capacity; ++j)
      out->list[j] = before_.list[j];
    for (size_t j = 0; j < b.data.capacity; ++j)
      out->data[j] = before_.data[j];
    i.queue.head = 0;
    i.queue.count = b.queue.count;
    i.queue.tail = i.queue.capacity ? b.queue.count % i.queue.capacity : 0;
    i.queue.version = b.queue.version;
    for (size_t j = 0; j < b.queue.count; ++j)
      out->queue[j] = before_.queue[(b.queue.head + j) % b.queue.capacity];
    i.dictionary.count = b.dictionary.count;
    i.dictionary.free_count = b.dictionary.free_count;
    i.dictionary.free_list = b.dictionary.count ? b.dictionary.free_list : -1;
    i.dictionary.version = b.dictionary.version;
    for (size_t j = 0; j < b.dictionary.count; ++j)
      out->entries[j] = before_.entries[j];
    for (size_t j = 0; j < b.dictionary.count; ++j) {
      auto &e = out->entries[j];
      if (e.hash < 0)
        continue;
      if (e.value < 0 || static_cast<uint32_t>(e.value) >= b.list.count ||
          !out->list[e.value] || e.hash != (e.key & 0x7fffffff))
        return false;
      const auto bucket =
          static_cast<size_t>(e.hash) % i.dictionary.bucket_capacity;
      e.next = out->buckets[bucket] - 1;
      out->buckets[bucket] = static_cast<int32_t>(j) + 1;
    }
    return true;
  }
};
} // namespace idoly_mp4_proflare_registry
